OLD_MEMBER_SCOPE = r"""CREATE OR REPLACE FUNCTION monkeydo_paid_visit_member_lock() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE member bigint; item_number integer; marker jsonb; intent core_membershippaidvisitintent%ROWTYPE;
    BEGIN
      IF TG_TABLE_NAME='core_membershipbenefitassignment' THEN member=NEW.purchase_id;
      ELSE SELECT item.purchase_id,item.number INTO member,item_number FROM core_membershipinvoice inv
        JOIN core_membershipinstallment item ON item.id=inv.installment_id WHERE inv.sale_id=NEW.sale_id; END IF;
      SELECT snapshot->'paid_visit_card' INTO marker FROM core_membershipdraft WHERE id=member;
      IF marker IS NULL THEN RETURN NEW; END IF;
      SELECT * INTO intent FROM core_membershippaidvisitintent WHERE purchase_id=member;
      IF EXISTS (SELECT 1 FROM core_membershippaidvisitrelease WHERE intent_id=intent.id AND kind='completed') THEN RETURN NEW; END IF;
      IF TG_TABLE_NAME='core_paymentoperation' THEN
      IF NEW.kind<>'receipt' THEN RETURN NEW; END IF;
      IF EXISTS (SELECT 1 FROM core_membershippaidvisitrecovery rec
        JOIN core_paymentoperation prev ON prev.id=rec.previous_id
        WHERE rec.intent_id=intent.id AND rec.operation_id=NEW.request_key
          AND rec.actor_id=NEW.actor_id AND rec.method_id=NEW.method_id
          AND NEW.kind='receipt' AND NEW.tender='card' AND NEW.purpose='member_purchase'
          AND NEW.amount=(marker->>'new_payment')::numeric
          AND NEW.allocation=rec.review->'allocation'
          AND item_number=1 AND prev.state IN ('declined','cancelled')
          AND NOT EXISTS (SELECT 1 FROM core_membershippaidvisitrelease WHERE intent_id=intent.id)
          AND NOT EXISTS (SELECT 1 FROM core_paymentoperation WHERE sale_id=NEW.sale_id
            AND (kind<>'receipt' OR state NOT IN ('declined','cancelled')))
          AND rec.sequence=(SELECT MAX(sequence) FROM core_membershippaidvisitrecovery WHERE intent_id=intent.id))
      THEN RETURN NEW; END IF;
      IF item_number=1 AND NEW.kind='receipt' AND NEW.tender='card'
        AND NEW.actor_id=(SELECT actor_id FROM core_membershippurchase WHERE membership_id=member)
        AND NEW.amount=(marker->>'new_payment')::numeric
        AND NOT EXISTS (SELECT 1 FROM core_membershippaidvisitrelease WHERE intent_id=intent.id)
        AND NOT EXISTS (SELECT 1 FROM core_paymentoperation WHERE sale_id=NEW.sale_id AND kind='receipt')
      THEN RETURN NEW; END IF;
      END IF;
      RAISE EXCEPTION 'Conditional paid visit funds cannot be collected or applied twice';
    END $$;"""

OLD_COMPLETE_SCOPE = r"""CREATE OR REPLACE FUNCTION monkeydo_paid_visit_card_complete() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE i core_membershippaidvisitintent%ROWTYPE; r core_membershippaidvisitrelease%ROWTYPE; member bigint;
    BEGIN
      IF TG_TABLE_NAME='core_membershippurchase' THEN member=NEW.membership_id;
        IF NOT EXISTS (SELECT 1 FROM core_membershipdraft WHERE id=member AND snapshot ? 'paid_visit_card') THEN RETURN NEW; END IF;
      ELSIF TG_TABLE_NAME='core_membershippaidvisitintent' THEN member=NEW.purchase_id;
      ELSIF TG_TABLE_NAME='core_visitmembershipconversion' THEN member=NEW.purchase_id;
        IF NOT EXISTS (SELECT 1 FROM core_membershipdraft WHERE id=member AND snapshot ? 'paid_visit_card') THEN RETURN NEW; END IF;
      ELSE SELECT purchase_id INTO member FROM core_membershippaidvisitintent WHERE id=NEW.intent_id; END IF;
      SELECT * INTO i FROM core_membershippaidvisitintent WHERE purchase_id=member;
      IF i.id IS NULL THEN RAISE EXCEPTION 'Conditional paid visit purchase requires its durable reservation'; END IF;
      SELECT * INTO r FROM core_membershippaidvisitrelease WHERE intent_id=i.id;
      IF r.kind='completed' THEN
        IF NOT EXISTS (SELECT 1 FROM core_membershipinstallment item JOIN core_membershipinvoice inv ON inv.installment_id=item.id
          JOIN core_membershipdraft d ON d.id=item.purchase_id JOIN core_visitmembershipconversion c ON c.id=r.conversion_id
          WHERE item.purchase_id=member AND item.number=1 AND c.purchase_id=member AND c.booking_id=i.booking_id
          AND c.id=i.conversion_key AND c.actor_id=i.actor_id AND c.details->'paid_visit_purchase'->>'offer'=i.fingerprint
          AND c.details->>'credit'=i.offer->'paid_visit'->'conversion'->>'credit'
          AND (c.details->>'credit')::numeric=(SELECT COALESCE(SUM(amount),0) FROM core_customercreditissue WHERE conversion_id=c.id)
          AND (i.offer->'paid_visit'->>'applied')::numeric=(SELECT COALESCE(SUM(app.amount),0) FROM core_customercreditapplication app WHERE app.sale_id=inv.sale_id)
          AND (i.offer->'paid_visit'->>'applied')::numeric=(SELECT COALESCE(SUM(a.amount),0) FROM core_customercreditallocation a
            JOIN core_customercreditapplication app ON app.id=a.application_id JOIN core_customercreditissue issue ON issue.id=a.issue_id
            WHERE app.sale_id=inv.sale_id AND issue.conversion_id=c.id AND app.actor_id=i.actor_id)
          AND (i.offer->'paid_visit'->>'new_payment')::numeric=(SELECT COALESCE(SUM(amount),0) FROM core_paymentoperation WHERE sale_id=inv.sale_id AND kind='receipt' AND state='succeeded')
          AND NOT EXISTS (SELECT 1 FROM core_paymentoperation op WHERE op.sale_id=inv.sale_id AND (
            op.kind<>'receipt' OR op.state NOT IN ('succeeded','declined','cancelled')
            OR (op.id IS DISTINCT FROM i.operation_id AND NOT EXISTS (
              SELECT 1 FROM core_membershippaidvisitrecovery rec WHERE rec.intent_id=i.id AND rec.operation_id=op.request_key))))
          AND NOT EXISTS (SELECT 1 FROM core_paymentoperation op WHERE op.sale_id=inv.sale_id AND op.state='succeeded'
            AND op.id IS DISTINCT FROM COALESCE((SELECT p.id FROM core_membershippaidvisitrecovery rec
              JOIN core_paymentoperation p ON p.request_key=rec.operation_id WHERE rec.intent_id=i.id ORDER BY rec.sequence DESC LIMIT 1),i.operation_id))
          AND (i.offer->'paid_visit'->>'applied')::numeric+(i.offer->'paid_visit'->>'new_payment')::numeric=(SELECT COALESCE(SUM(net+fee+item_tax+fee_tax),0) FROM core_financialline WHERE sale_id=inv.sale_id)
          AND NOT EXISTS (SELECT 1 FROM core_financiallineadjustment a JOIN core_financialline l ON l.id=a.line_id WHERE l.sale_id=inv.sale_id)
          AND EXISTS (SELECT 1 FROM core_membershipbenefitassignment a JOIN core_membershipbenefitstate cur ON cur.assignment_id=a.id
            WHERE a.purchase_id=member AND a.booking_id=i.booking_id AND a.quote_id=c.updated_quote_id AND cur.status='used'))
        THEN RAISE EXCEPTION 'Paid visit completion requires known funding, exact credit and actual benefit use'; END IF;
      ELSE
        IF EXISTS (SELECT 1 FROM core_visitmembershipconversion WHERE booking_id=i.booking_id AND purchase_id=member)
          OR EXISTS (SELECT 1 FROM core_customercreditapplication app JOIN core_membershipinvoice inv ON inv.sale_id=app.sale_id
            JOIN core_membershipinstallment item ON item.id=inv.installment_id WHERE item.purchase_id=member)
          OR EXISTS (SELECT 1 FROM core_membershipbenefitassignment WHERE purchase_id=member)
        THEN RAISE EXCEPTION 'An unresolved paid visit cannot create credit or membership benefits'; END IF;
      END IF;
      RETURN NEW;
    END $$;"""

OLD_CANCELLED_SCOPE = r"""CREATE OR REPLACE FUNCTION monkeydo_paid_visit_cancelled_scope() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE i core_membershippaidvisitintent%ROWTYPE; c core_membershipcancellation%ROWTYPE;
      sale uuid; line uuid; paid numeric; returned numeric; fee numeric; invoice numeric; reserved numeric;
    BEGIN
      SELECT * INTO i FROM core_membershippaidvisitintent WHERE id=NEW.release_id;
      SELECT * INTO c FROM core_membershipcancellation WHERE id=NEW.cancellation_id;
      PERFORM 1 FROM core_booking WHERE id=i.booking_id FOR UPDATE;
      PERFORM pg_advisory_xact_lock(73219, ('x'||substr(replace(i.source_sale_id::text,'-',''),1,8))::bit(32)::int);
      SELECT inv.sale_id INTO sale FROM core_membershipinvoice inv JOIN core_membershipinstallment item ON item.id=inv.installment_id WHERE item.purchase_id=i.purchase_id AND item.number=1;
      SELECT id INTO line FROM core_financialline WHERE sale_id=sale;
      SELECT COALESCE(SUM(amount) FILTER(WHERE kind='receipt' AND state='succeeded'),0), COALESCE(SUM(amount) FILTER(WHERE kind<>'receipt' AND state='succeeded'),0) INTO paid,returned FROM core_paymentoperation WHERE sale_id=sale;
      SELECT COALESCE(SUM((part->>'fee')::numeric),0) INTO fee FROM core_paymentoperation op,jsonb_array_elements(op.allocation) part WHERE op.sale_id=sale AND op.kind='receipt' AND op.state='succeeded';
      SELECT COALESCE(SUM(l.net+l.fee+l.item_tax+l.fee_tax+COALESCE((SELECT SUM(a.net+a.fee+a.item_tax+a.fee_tax) FROM core_financiallineadjustment a WHERE a.line_id=l.id),0)),0) INTO invoice FROM core_financialline l WHERE l.sale_id=sale;
      reserved=(i.offer->'paid_visit'->>'applied')::numeric;
      IF i.id IS NULL OR c.id IS NULL OR c.purchase_id<>i.purchase_id
        OR c.stopped_on>(NEW.created_at AT TIME ZONE 'America/New_York')::date
        OR NOT EXISTS (SELECT 1 FROM core_membershipbilling WHERE purchase_id=i.purchase_id AND stopped_on=c.stopped_on)
        OR NOT EXISTS (SELECT 1 FROM auth_user WHERE id=NEW.actor_id AND is_active AND is_staff AND is_superuser)
        OR length(btrim(NEW.reason)) NOT BETWEEN 1 AND 500
        OR EXISTS (SELECT 1 FROM core_membershippaidvisitrelease WHERE intent_id=i.id)
        OR EXISTS (SELECT 1 FROM core_membershipbenefitassignment WHERE purchase_id=i.purchase_id)
        OR EXISTS (SELECT 1 FROM core_visitmembershipconversion WHERE purchase_id=i.purchase_id)
        OR EXISTS (SELECT 1 FROM core_customercreditapplication WHERE sale_id=sale)
        OR EXISTS (SELECT 1 FROM core_paymentoperation op JOIN core_membershipinvoice inv ON inv.sale_id=op.sale_id JOIN core_membershipinstallment item ON item.id=inv.installment_id WHERE item.purchase_id=i.purchase_id AND op.state NOT IN ('succeeded','declined','cancelled'))
        OR paid<=0 OR paid IS DISTINCT FROM (i.offer->'paid_visit'->>'new_payment')::numeric
        OR returned IS DISTINCT FROM c.refund_amount OR paid-returned<fee
        OR reserved<=0 OR invoice-(paid-returned) IS DISTINCT FROM reserved
        OR (SELECT COUNT(*) FROM core_financialline WHERE sale_id=sale)<>1
        OR EXISTS (SELECT 1 FROM core_financialline WHERE sale_id=sale AND (item_tax<>0 OR fee_tax<>0))
        OR EXISTS (SELECT 1 FROM core_financiallineadjustment a WHERE a.line_id=line AND (a.reason<>'membership_refund' OR a.fee<>0 OR a.item_tax<>0 OR a.fee_tax<>0))
        OR EXISTS (SELECT 1 FROM core_paymentoperation op,jsonb_array_elements(op.allocation) part WHERE op.sale_id=sale AND op.state='succeeded' AND ((part->>'item_tax')::numeric<>0 OR (part->>'fee_tax')::numeric<>0 OR (op.kind<>'receipt' AND (part->>'fee')::numeric<>0)))
        OR EXISTS (SELECT 1 FROM core_paymentoperation op LEFT JOIN core_membershiprefundattempt attempt ON attempt.operation_id=op.id LEFT JOIN core_membershiprefundplan plan ON plan.id=attempt.plan_id LEFT JOIN core_paymentoperation original ON original.id=op.original_id WHERE op.sale_id=sale AND op.state='succeeded' AND op.kind<>'receipt' AND (op.kind<>'refund' OR plan.cancellation_id IS DISTINCT FROM c.id OR op.original_id IS DISTINCT FROM plan.original_id OR original.sale_id IS DISTINCT FROM sale OR op.tender<>'card' OR op.method_id IS DISTINCT FROM original.method_id))
        OR c.refund_amount IS DISTINCT FROM (SELECT COALESCE(SUM(amount),0) FROM core_membershiprefundplan WHERE cancellation_id=c.id)
        OR EXISTS (SELECT 1 FROM core_membershiprefundplan p WHERE p.cancellation_id=c.id AND (
          p.amount IS DISTINCT FROM (SELECT COALESCE(SUM(op.amount),0) FROM core_membershiprefundattempt a JOIN core_paymentoperation op ON op.id=a.operation_id WHERE a.plan_id=p.id AND op.state='succeeded')
          OR EXISTS (SELECT 1 FROM core_membershiprefundattempt a JOIN core_paymentoperation op ON op.id=a.operation_id WHERE a.plan_id=p.id AND op.state IN ('ready','sending','unknown','action'))))
        OR NEW.facts->>'intent' IS DISTINCT FROM i.id::text OR NEW.facts->>'purchase' IS DISTINCT FROM i.purchase_id::text
        OR NEW.facts->>'actor' IS DISTINCT FROM NEW.actor_id::text OR NEW.facts->>'offer' IS DISTINCT FROM i.fingerprint
        OR NEW.facts->>'cancellation' IS DISTINCT FROM c.id::text OR NEW.facts->>'cancellation_fingerprint' IS DISTINCT FROM c.fingerprint
        OR NEW.facts->>'stopped_on' IS DISTINCT FROM c.stopped_on::text
        OR NEW.facts->>'on' IS DISTINCT FROM ((NEW.created_at AT TIME ZONE 'America/New_York')::date)::text
        OR NEW.facts->>'membership_sale' IS DISTINCT FROM sale::text OR NEW.facts->>'line' IS DISTINCT FROM line::text
        OR (NEW.facts->>'received')::numeric IS DISTINCT FROM paid OR (NEW.facts->>'returned')::numeric IS DISTINCT FROM returned
        OR (NEW.facts->>'retained')::numeric IS DISTINCT FROM paid-returned OR (NEW.facts->>'retained_fee')::numeric IS DISTINCT FROM fee
        OR (NEW.facts->>'retained_principal')::numeric IS DISTINCT FROM paid-returned-fee
        OR (NEW.facts->>'membership_total')::numeric IS DISTINCT FROM invoice OR (NEW.facts->>'uncollected')::numeric IS DISTINCT FROM reserved
        OR NEW.facts->>'source' IS DISTINCT FROM i.source_sale_id::text
        OR NEW.facts->>'booking' IS DISTINCT FROM i.booking_id::text
        OR NOT EXISTS (SELECT 1 FROM core_booking WHERE id=i.booking_id AND attendance='arrived' AND workflow='integrated_v1' AND edit_version::text=NEW.facts->>'booking_version')
        OR length(COALESCE(NEW.facts->>'reviewed_hash',''))<>64 OR length(NEW.fingerprint)<>64
        OR NEW.facts->>'adjustment_key' IS NULL
      THEN RAISE EXCEPTION 'Cancelled source release requires effective owner cancellation, completed chosen refunds and exact uncollected funds'; END IF;
      RETURN NEW;
    END $$;"""


def install(apps, editor):
    if editor.connection.vendor == "postgresql":
        for sql in (MANUAL_SQL, MEMBER_SCOPE, COMPLETE_SCOPE, CANCELLED_SCOPE):
            editor.execute(sql, params=None)
        editor.execute(
            "CREATE TRIGGER core_membershippaidvisitmanualpayment_immutable BEFORE UPDATE OR DELETE ON core_membershippaidvisitmanualpayment FOR EACH ROW EXECUTE FUNCTION monkeydo_financial_immutable()"
        )
        editor.execute(
            "CREATE TRIGGER core_membershippaidvisitmanualpayment_scope BEFORE INSERT ON core_membershippaidvisitmanualpayment FOR EACH ROW EXECUTE FUNCTION monkeydo_paid_visit_manual_scope()"
        )
        editor.execute(
            "CREATE CONSTRAINT TRIGGER core_membershippaidvisitmanualpayment_backed AFTER INSERT ON core_membershippaidvisitmanualpayment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION monkeydo_paid_visit_manual_backed()"
        )
        editor.execute(
            "CREATE CONSTRAINT TRIGGER core_paid_visit_manual_complete AFTER INSERT ON core_membershippaidvisitmanualpayment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION monkeydo_paid_visit_card_complete()"
        )
        editor.execute(
            "CREATE TRIGGER core_paid_visit_manual_fee BEFORE INSERT ON core_financiallineadjustment FOR EACH ROW EXECUTE FUNCTION monkeydo_paid_visit_manual_fee()"
        )
    elif editor.connection.vendor == "sqlite":
        for event in ("update", "delete"):
            editor.execute(
                f"CREATE TRIGGER core_membershippaidvisitmanualpayment_{event}_immutable BEFORE {event.upper()} ON core_membershippaidvisitmanualpayment BEGIN SELECT RAISE(ABORT, 'Received remainder is immutable'); END"
            )


def remove(apps, editor):
    if (
        apps.get_model("core", "MembershipPaidVisitManualPayment")
        .objects.using(editor.connection.alias)
        .exists()
    ):
        raise RuntimeError(
            "Received paid-visit membership payments have been used; keep compatible code and fix forward."
        )
    if editor.connection.vendor == "postgresql":
        editor.execute("DROP TRIGGER core_paid_visit_manual_fee ON core_financiallineadjustment")
        for suffix in ("immutable", "scope", "backed"):
            editor.execute(
                f"DROP TRIGGER core_membershippaidvisitmanualpayment_{suffix} ON core_membershippaidvisitmanualpayment"
            )
        editor.execute(
            "DROP TRIGGER core_paid_visit_manual_complete ON core_membershippaidvisitmanualpayment"
        )
        for sql in (OLD_MEMBER_SCOPE, OLD_COMPLETE_SCOPE, OLD_CANCELLED_SCOPE):
            editor.execute(sql, params=None)
        for name in ("scope", "fee", "backed"):
            editor.execute(f"DROP FUNCTION monkeydo_paid_visit_manual_{name}()")
        editor.execute("DROP FUNCTION monkeydo_paid_visit_manual_completed(uuid)")
    elif editor.connection.vendor == "sqlite":
        for event in ("update", "delete"):
            editor.execute(f"DROP TRIGGER core_membershippaidvisitmanualpayment_{event}_immutable")


